style.css:
/* Eliminar completamente el botón de Estados */
button[aria-label="Estado"] {
    display: none !important;        /* Lo elimina de la vista y del layout */
    pointer-events: none !important; /* Por si alguna regla rara lo revive */
    visibility: hidden !important;   /* Extra seguridad */
    opacity: 0 !important;
    width: 0 !important;
    height: 0 !important;
    overflow: hidden !important;
}
